const JENIS_CONTOH = {
  "pakaian": "Pakaian",
  "rumah": "Rumah",
  "alat-musik": "Alat Musik",
  "makanan": "Makanan",
};

window.ambilBudaya = function (slugProvinsi, kategori) {
  const data = window.DATA_BUDAYA[slugProvinsi] && window.DATA_BUDAYA[slugProvinsi][kategori];
  if (data && data.length) return data;

  // Item contoh (sementara)
  return Array.from({ length: 6 }, (_, i) => ({
    nama: `Contoh ${JENIS_CONTOH[kategori] || "Budaya"} ${i + 1}`,
    deskripsi: "Penjelasan tentang budaya ini akan segera hadir. Isi nama, deskripsi, gambar, dan tautan model 3D di file data-budaya.js.",
    gambar: null,
    model3d: null,
  }));
};

/* Cari item berdasarkan teks yang terbaca dari QR (cocok dengan "kode" item atau "kode" varian) */
window.cariBerdasarkanKode = function (teks) {
  const kode = String(teks).trim();
  if (!kode) return null;
  for (const prov of Object.keys(window.DATA_BUDAYA)) {
    for (const kat of Object.keys(window.DATA_BUDAYA[prov])) {
      const daftar = window.DATA_BUDAYA[prov][kat];
      for (let i = 0; i < daftar.length; i++) {
        const item = daftar[i];
        if (item.kode && item.kode === kode) return { item, provinsi: prov, kategori: kat, indeks: i, varian: 0 };
        const v = (item.varian || []).findIndex((x) => x.kode && x.kode === kode);
        if (v >= 0) return { item, provinsi: prov, kategori: kat, indeks: i, varian: v };
      }
    }
  }
  return null;
};
